result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_queue_stress.py", "content": """"Correctness stress test: 4 producers x 4 consumers x 100k items per queue class.

Both queue classes are exercised through a common interface (put/get/get_nowait),
which is all the producers/consumers rely on. Assertions:

  * no loss   : every (producer_id, seq) pair is received exactly once
  * no dup    : no pair is received twice
  * in-order  : within each consumer, seqs from a given producer are strictly
                increasing (i.e. FIFO order is preserved up to whichever
                consumer happened to grab each item)
"""

import queue
import threading

import pytest

ITEMS_PER_PRODUCER = 100_000
TOTAL_ITEMS = ITEMS_PER_PRODUCER * 4  # 400,000
NUM_PRODUCERS = 4
NUM_CONSUMERS = 4


# --- common interface -------------------------------------------------------

def make_queue(cls):
    """All queue classes here share put()/get()/get_nowait()."""
    return cls()


def producer(q, pid, n):
    for seq in range(n):
        q.put((pid, seq))


def consumer(q, out, errors):
    """Drain until sentinel None; record items and any get() exceptions."""
    while True:
        item = q.get()
        if item is None:
            return
        try:
            out.append(item)
        except Exception as exc:  # pragma: no cover - defensive
            errors.append(exc)


# --- test -------------------------------------------------------------------

@pytest.mark.parametrize("queue_cls", [queue.SimpleQueue, queue.Queue])
def test_no_loss_no_dup_in_order(queue_cls):
    q = make_queue(queue_cls)
    received = []          # list of (pid, seq), appended under lock
    lock = threading.Lock()
    # last seq seen per (consumer, producer): proves in-order delivery
    last_seen = [dict() for _ in range(NUM_CONSUMERS)]
    order_violations = []
    errors = []

    def consumer_tracked(cid):
        while True:
            item = q.get()
            if item is None:
                return
            pid, seq = item
            with lock:
                prev = last_seen[cid].get(pid, -1)
                if seq <= prev:
                    order_violations.append((cid, pid, prev, seq))
                last_seen[cid][pid] = seq
                received.append(item)

    producers = [
        threading.Thread(target=producer, args=(q, pid, ITEMS_PER_PRODUCER))
        for pid in range(NUM_PRODUCERS)
    ]
    consumers = [
        threading.Thread(target=consumer_tracked, args=(cid,))
        for cid in range(NUM_CONSUMERS)
    ]

    for t in consumers:
        t.start()
    for t in producers:
        t.start()
    for t in producers:
        t.join()
    for _ in consumers:  # one sentinel per consumer
        q.put(None)
    for t in consumers:
        t.join()

    assert not errors
    assert not order_violations, f"out-of-order deliveries: {order_violations[:5]}"

    # no loss + no duplication: multiset must be exactly {(pid, seq)}
    assert len(received) == TOTAL_ITEMS
    counts = {}
    for pid, seq in received:
        counts[(pid, seq)] = counts.get((pid, seq), 0) + 1
    expected_per_pid = ITEMS_PER_PRODUCER
    for pid in range(NUM_PRODUCERS):
        assert len([1 for p, _ in received if p == pid]) == expected_per_pid
    duplicates = {k: v for k, v in counts.items() if v > 1}
    missing = [
        (pid, s)
        for pid in range(NUM_PRODUCERS)
        for s in range(ITEMS_PER_PRODUCER)
        if counts.get((pid, s), 0) == 0
    ]
    assert not duplicates, f"duplicated items: {list(duplicates.items())[:5]}"
    assert not missing, f"lost items: {missing[:5]}"


if __name__ == "__main__":
    raise SystemExit(pytest.main([__file__, "-v"]))
